wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

const MAX_QUESTION: usize = 512;

fn bounded(mut s: String) -> String {
    if s.len() > MAX_QUESTION {
        let mut end = MAX_QUESTION;
        while !s.is_char_boundary(end) {
            end -= 1;
        }
        s.truncate(end);
    }
    s
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let q = query.query;
        let question = bounded(q.question);
        let knowledge = crate::aap::caps::kb_read::lookup(&question);
        ConversationContext {
            intent: q.intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
